draw((3*pi/2,tan(-1.3))--(3*pi/2,tan(1.3)),dashed);
draw((0,0)--(2*pi,0));
draw((pi,0.2)--(pi,-0.2));
draw((2*pi,0.2)--(2*pi,-0.2));
draw((0,2)--(2*pi,2),blue);
draw((0,1/2)--(2*pi,1/2),blue);

